"use client";

import { useEffect, useId, useRef, type ReactNode } from "react";
import type { Key } from "react-aria-components";
import { Checkbox, type CheckboxProps } from "../checkbox/checkbox";
import { NumberField, type NumberFieldProps } from "../number-field/number-field";
import { Select, type SelectProps } from "../select/select";
import { Switch, type SwitchProps } from "../switch/switch";
import { TextField, type TextFieldProps } from "../text-field/text-field";
import { fieldError } from "../utils/field";
import { useFormContext } from "./form";
import { useEngineField, type AsyncFieldValidator, type FieldValidator } from "./form-engine";

export interface FieldOptions<TValue = any> {
  /** Name of the value in the form. Nested names work: "address.city", "lines[0].qty". */
  name: string;
  /** How this field is named in the ErrorSummary. Use the visible label. */
  label?: string;
  /** Adds a built-in check that the field is not empty. */
  isRequired?: boolean;
  /** The message when a required field is empty. */
  requiredMessage?: string;
  /** Returns a message when the value is wrong. Gets the value and all values. */
  validate?: FieldValidator<TValue>;
  /** The same, for a check that needs the network. Runs after the value settles. */
  validateAsync?: AsyncFieldValidator<TValue>;
}

/** What a Field hands to its render function. */
export interface FieldState<TValue = any> {
  name: string;
  value: TValue;
  setValue(value: TValue): void;
  onBlur(): void;
  isInvalid: boolean;
  /** The first error to show, from the field's validator, the schema, or the server. */
  errorMessage?: string;
  errors: string[];
  isTouched: boolean;
  isValidating: boolean;
  /** For TextField and other inputs that take text. */
  inputProps: {
    name: string;
    value: string;
    onChange(value: string): void;
    onBlur(): void;
    isInvalid?: boolean;
    errorMessage?: string;
    isRequired?: boolean;
    validationBehavior: "aria";
  };
  /** For NumberField. An empty field is stored as null. */
  numberProps: {
    name: string;
    value: number;
    onChange(value: number): void;
    onBlur(): void;
    isInvalid?: boolean;
    errorMessage?: string;
    isRequired?: boolean;
    validationBehavior: "aria";
  };
  /** For Select and other pickers that use a key. */
  selectProps: {
    name: string;
    selectedKey: Key | null;
    onSelectionChange(key: Key | null): void;
    onBlur(): void;
    isInvalid?: boolean;
    errorMessage?: string;
    isRequired?: boolean;
    validationBehavior: "aria";
  };
  /** For Checkbox and Switch. */
  checkProps: {
    name: string;
    isSelected: boolean;
    onChange(isSelected: boolean): void;
    onBlur(): void;
    isInvalid?: boolean;
  };
}

const isEmpty = (value: unknown) =>
  value === undefined ||
  value === null ||
  value === false ||
  (typeof value === "string" && value.trim() === "") ||
  (typeof value === "number" && Number.isNaN(value)) ||
  (Array.isArray(value) && value.length === 0);

export interface FieldProps<TValue = any> extends FieldOptions<TValue> {
  children: (field: FieldState<TValue>) => ReactNode;
}

/**
 * Connects one value of the Form to any input. The render function receives
 * the value, the error and ready-made prop sets for the library's inputs;
 * the inputs already link their label, help text and error with aria-describedby
 * and set aria-invalid.
 */
export function Field<TValue = any>({ name, label, isRequired, requiredMessage, validate, validateAsync, children }: FieldProps<TValue>) {
  const form = useFormContext();
  const { serverErrors, clearServerError, labels } = form;

  const required = isRequired
    ? (value: TValue, all: unknown) => (isEmpty(value) ? (requiredMessage ?? (label ? `${label} is required` : "This field is required")) : validate?.(value, all))
    : validate;
  const binding = useEngineField<TValue>(form.engine, name, { validate: required as FieldValidator<TValue> | undefined, validateAsync });

  useEffect(() => {
    if (label) labels.set(name, label);
    return () => {
      labels.delete(name);
    };
  }, [labels, name, label]);

  // A server error stays until the person changes the value.
  const serverError = serverErrors[name];
  const seenAt = useRef<{ value: unknown } | null>(null);
  if (serverError && !seenAt.current) seenAt.current = { value: binding.value };
  if (!serverError) seenAt.current = null;
  useEffect(() => {
    if (serverError && seenAt.current && !Object.is(seenAt.current.value, binding.value)) {
      seenAt.current = null;
      clearServerError(name);
    }
  }, [binding.value, serverError, clearServerError, name]);

  const errors = serverError ? [serverError, ...binding.errors] : binding.errors;
  const errorMessage = errors[0];
  const isInvalid = errors.length > 0;
  // Only passed when true: a defined isInvalid would switch off the input's own checks.
  const invalid = isInvalid ? true : undefined;
  const asRequired = isRequired || undefined;

  const state: FieldState<TValue> = {
    name,
    value: binding.value,
    setValue: binding.setValue,
    onBlur: binding.blur,
    isInvalid,
    errorMessage,
    errors,
    isTouched: binding.isTouched,
    isValidating: binding.isValidating,
    inputProps: {
      name,
      value: (binding.value as unknown as string | undefined) ?? "",
      onChange: (value) => binding.setValue(value as unknown as TValue),
      onBlur: binding.blur,
      isInvalid: invalid,
      errorMessage,
      isRequired: asRequired,
      validationBehavior: "aria",
    },
    numberProps: {
      name,
      value: typeof binding.value === "number" ? binding.value : Number.NaN,
      onChange: (value) => binding.setValue((Number.isNaN(value) ? null : value) as unknown as TValue),
      onBlur: binding.blur,
      isInvalid: invalid,
      errorMessage,
      isRequired: asRequired,
      validationBehavior: "aria",
    },
    selectProps: {
      name,
      selectedKey: ((binding.value as unknown as Key | undefined) ?? null) as Key | null,
      onSelectionChange: (key) => binding.setValue(key as unknown as TValue),
      onBlur: binding.blur,
      isInvalid: invalid,
      errorMessage,
      isRequired: asRequired,
      validationBehavior: "aria",
    },
    checkProps: {
      name,
      isSelected: Boolean(binding.value),
      onChange: (selected) => binding.setValue(selected as unknown as TValue),
      onBlur: binding.blur,
      isInvalid: invalid,
    },
  };

  // The wrapper has no box of its own; it only lets the ErrorSummary find the control by name.
  return (
    <div data-rd-field={name} className="contents">
      {children(state)}
    </div>
  );
}

type Bound<TProps> = Omit<
  TProps,
  "value" | "defaultValue" | "onChange" | "name" | "isInvalid" | "errorMessage" | "validate" | "validationBehavior" | "onBlur" | "isRequired"
> &
  Pick<FieldOptions, "name" | "isRequired" | "requiredMessage" | "validate" | "validateAsync">;

export type FormTextFieldProps = Bound<TextFieldProps>;
export type FormNumberFieldProps = Bound<NumberFieldProps>;
export type FormSelectProps = Bound<SelectProps>;

/** A TextField connected to the Form by name. */
export function FormTextField({ name, isRequired, requiredMessage, validate, validateAsync, ...props }: FormTextFieldProps) {
  return (
    <Field<string> name={name} label={props.label} isRequired={isRequired} requiredMessage={requiredMessage} validate={validate} validateAsync={validateAsync}>
      {(f) => <TextField {...props} {...f.inputProps} />}
    </Field>
  );
}

/** A NumberField connected to the Form by name. */
export function FormNumberField({ name, isRequired, requiredMessage, validate, validateAsync, ...props }: FormNumberFieldProps) {
  return (
    <Field<number | null> name={name} label={props.label} isRequired={isRequired} requiredMessage={requiredMessage} validate={validate} validateAsync={validateAsync}>
      {(f) => <NumberField {...props} {...f.numberProps} />}
    </Field>
  );
}

/** A Select connected to the Form by name. The value is the key of the chosen item. */
export function FormSelect({ name, isRequired, requiredMessage, validate, validateAsync, ...props }: FormSelectProps) {
  return (
    <Field<Key | null> name={name} label={props.label} isRequired={isRequired} requiredMessage={requiredMessage} validate={validate} validateAsync={validateAsync}>
      {(f) => <Select {...props} {...f.selectProps} />}
    </Field>
  );
}

type BoundCheck<TProps> = Omit<TProps, "isSelected" | "defaultSelected" | "onChange" | "name" | "isInvalid" | "onBlur"> &
  Pick<FieldOptions, "name" | "requiredMessage" | "validate" | "validateAsync"> & { isRequired?: boolean };

export type FormCheckboxProps = BoundCheck<CheckboxProps>;
export type FormSwitchProps = BoundCheck<SwitchProps>;

/** The error under a checkbox or switch, linked to it with aria-describedby. */
function CheckError({ id, children }: { id: string; children?: string }) {
  return children ? (
    <p id={id} className={fieldError}>
      {children}
    </p>
  ) : null;
}

/** A Checkbox connected to the Form by name. isRequired means it must be checked. */
export function FormCheckbox({ name, isRequired, requiredMessage, validate, validateAsync, children, ...props }: FormCheckboxProps) {
  const errorId = useId();
  const label = typeof children === "string" ? children : undefined;
  return (
    <Field<boolean> name={name} label={label} isRequired={isRequired} requiredMessage={requiredMessage} validate={validate} validateAsync={validateAsync}>
      {(f) => (
        <div className="flex flex-col gap-1">
          <Checkbox {...(props as CheckboxProps)} {...f.checkProps} aria-describedby={f.errorMessage ? errorId : undefined}>
            {children}
          </Checkbox>
          <CheckError id={errorId}>{f.errorMessage}</CheckError>
        </div>
      )}
    </Field>
  );
}

/** A Switch connected to the Form by name. */
export function FormSwitch({ name, isRequired, requiredMessage, validate, validateAsync, children, ...props }: FormSwitchProps) {
  const errorId = useId();
  const label = typeof children === "string" ? children : undefined;
  return (
    <Field<boolean> name={name} label={label} isRequired={isRequired} requiredMessage={requiredMessage} validate={validate} validateAsync={validateAsync}>
      {(f) => {
        const { isInvalid: _invalid, ...bound } = f.checkProps;
        return (
          <div className="flex flex-col gap-1">
            <Switch {...(props as SwitchProps)} {...bound} aria-describedby={f.errorMessage ? errorId : undefined}>
              {children}
            </Switch>
            <CheckError id={errorId}>{f.errorMessage}</CheckError>
          </div>
        );
      }}
    </Field>
  );
}

// Finding the control to focus inside a field or a repeating row. Inputs from
// React Aria keep a hidden twin for native form posts; those are skipped.

const FOCUSABLE =
  'input:not([type="hidden"]), textarea, select, button, a[href], [role="combobox"], [role="spinbutton"], [role="switch"], [tabindex="0"]';

function isUsable(el: Element): boolean {
  if (el.closest('[aria-hidden="true"]')) return false;
  if (el.getAttribute("tabindex") === "-1") return false;
  if (el instanceof HTMLButtonElement || el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || el instanceof HTMLSelectElement) {
    if (el.disabled) return false;
  }
  return el.getAttribute("aria-disabled") !== "true";
}

/** The first control inside `root` that a person can reach with the keyboard. */
export function firstFocusable(root: Element | null | undefined): HTMLElement | null {
  if (!root) return null;
  return ([...root.querySelectorAll(FOCUSABLE)].find(isUsable) as HTMLElement | undefined) ?? null;
}

/** The wrapper a Field or FieldArray puts around its control, found by name. */
export function findFieldRoot(form: Element | null | undefined, name: string): Element | null {
  if (!form) return null;
  return [...form.querySelectorAll("[data-rd-field]")].find((el) => el.getAttribute("data-rd-field") === name) ?? null;
}

"use client";

// The only file that knows which form engine runs underneath (TanStack Form).
// Everything else in form/, field-array/ and error-summary/ talks to the small
// interface below, so the engine can be swapped by rewriting this one file.
// Nothing here fetches data: it holds values, runs validators and reports errors.

import { revalidateLogic, useField, useForm, useStore, type StandardSchemaV1 } from "@tanstack/react-form";
import { useMemo } from "react";

/** Any validator that follows the Standard Schema spec (Zod, Valibot, ArkType...). */
export type FormSchema<TValues = any> = StandardSchemaV1<TValues, any>;

/** When errors first appear. After a failed submit they always update as the person types. */
export type ValidateOn = "submit" | "blur" | "change";

/** A message when the value is wrong, nothing when it is fine. */
export type FieldValidator<TValue = any, TValues = any> = (
  value: TValue,
  values: TValues,
) => string | null | undefined | false | void;

export type AsyncFieldValidator<TValue = any, TValues = any> = (
  value: TValue,
  values: TValues,
) => Promise<string | null | undefined | false | void>;

export interface FormEngineOptions<TValues> {
  defaultValues: TValues;
  schema?: FormSchema<TValues>;
  validateOn?: ValidateOn;
  /** Runs when every validator passes. */
  onSubmit: (values: TValues) => void | Promise<void>;
  /** Runs when a submit is stopped by a validator. */
  onInvalid?: () => void;
}

export interface FormEngine<TValues = any> {
  submit(): Promise<void>;
  reset(values?: TValues): void;
  getValues(): TValues;
  setValue(name: string, value: unknown): void;
  /** The engine's own form object. Only this file reads it. */
  readonly api: unknown;
}

export interface FieldOptions<TValue = any, TValues = any> {
  validate?: FieldValidator<TValue, TValues>;
  validateAsync?: AsyncFieldValidator<TValue, TValues>;
  asyncDebounceMs?: number;
}

export interface FieldBinding<TValue = any> {
  value: TValue;
  errors: string[];
  isTouched: boolean;
  isValidating: boolean;
  setValue(value: TValue): void;
  blur(): void;
}

export interface ArrayBinding<TRow = any> {
  length: number;
  errors: string[];
  push(row: TRow): void;
  insert(index: number, row: TRow): void;
  remove(index: number): void;
  move(from: number, to: number): void;
}

export interface FieldErrorEntry {
  name: string;
  message: string;
}

// The form object is typed loosely on purpose: the adapter is the boundary.
const asApi = (engine: FormEngine) => engine.api as any;

function messageOf(issue: unknown): string | undefined {
  if (typeof issue === "string") return issue || undefined;
  if (issue && typeof issue === "object" && "message" in issue) {
    const m = (issue as { message?: unknown }).message;
    return typeof m === "string" && m ? m : undefined;
  }
  return undefined;
}

function messagesOf(errors: unknown): string[] {
  const list = Array.isArray(errors) ? errors : errors ? [errors] : [];
  return [...new Set(list.map(messageOf).filter((m): m is string => Boolean(m)))];
}

export function useFormEngine<TValues>(options: FormEngineOptions<TValues>): FormEngine<TValues> {
  const form = useForm({
    defaultValues: options.defaultValues as any,
    validationLogic: revalidateLogic({ mode: options.validateOn ?? "submit", modeAfterSubmission: "change" }),
    validators: options.schema ? { onDynamic: options.schema as any } : undefined,
    onSubmit: async ({ value }: { value: any }) => options.onSubmit(value as TValues),
    onSubmitInvalid: () => options.onInvalid?.(),
  } as any) as any;

  return useMemo<FormEngine<TValues>>(
    () => ({
      api: form,
      submit: () => form.handleSubmit(),
      reset: (values) => form.reset(values),
      getValues: () => form.state.values,
      setValue: (name, value) => form.setFieldValue(name, value),
    }),
    [form],
  );
}

/** Reads values for display or derived numbers. Return something cheap to compare, such as a number. */
export function useEngineValues<TValues, TResult>(engine: FormEngine<TValues>, select: (values: TValues) => TResult): TResult {
  return useStore(asApi(engine).store, (state: { values: TValues }) => select(state.values)) as TResult;
}

export function useEngineField<TValue = any>(
  engine: FormEngine,
  name: string,
  options: FieldOptions<TValue> = {},
): FieldBinding<TValue> {
  const { validate, validateAsync, asyncDebounceMs = 300 } = options;
  const field = useField({
    form: asApi(engine),
    name,
    validators: {
      ...(validate ? { onDynamic: ({ value, fieldApi }: any) => validate(value, fieldApi.form.state.values) || undefined } : {}),
      ...(validateAsync
        ? {
            onDynamicAsync: async ({ value, fieldApi }: any) => (await validateAsync(value, fieldApi.form.state.values)) || undefined,
            onDynamicAsyncDebounceMs: asyncDebounceMs,
          }
        : {}),
    },
  } as any) as any;
  const meta = field.state.meta;
  return {
    value: field.state.value,
    errors: messagesOf(meta.errors),
    isTouched: Boolean(meta.isTouched),
    isValidating: Boolean(meta.isValidating),
    setValue: (value) => field.handleChange(value),
    blur: () => field.handleBlur(),
  };
}

export function useEngineArray<TRow = any>(
  engine: FormEngine,
  name: string,
  options: { validate?: FieldValidator<TRow[]> } = {},
): ArrayBinding<TRow> {
  const { validate } = options;
  const field = useField({
    form: asApi(engine),
    name,
    mode: "array",
    validators: validate ? { onDynamic: ({ value, fieldApi }: any) => validate(value ?? [], fieldApi.form.state.values) || undefined } : undefined,
  } as any) as any;
  const rows = field.state.value;
  return {
    length: Array.isArray(rows) ? rows.length : 0,
    errors: messagesOf(field.state.meta.errors),
    push: (row) => field.pushValue(row),
    insert: (index, row) => field.insertValue(index, row),
    remove: (index) => field.removeValue(index),
    move: (from, to) => field.moveValue(from, to),
  };
}

/** The first message of every field that has errors, in the order the fields were added. */
export function useEngineErrors(engine: FormEngine): FieldErrorEntry[] {
  const meta = useStore(asApi(engine).store, (state: { fieldMeta: Record<string, { errors?: unknown }> }) => state.fieldMeta);
  return useMemo(
    () =>
      Object.entries((meta ?? {}) as Record<string, { errors?: unknown }>).flatMap(([name, m]) => {
        const message = messagesOf(m?.errors)[0];
        return message ? [{ name, message }] : [];
      }),
    [meta],
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type FormHTMLAttributes,
  type ReactNode,
  type RefObject,
} from "react";
import { formDefaults, type FormSpecProps } from "../generated/form.types";
import { Button, type ButtonProps } from "../button/button";
import { cx } from "../utils/cx";
import type { ActionState } from "../utils/state";
import { findFieldRoot, firstFocusable } from "./focus";
import { useEngineValues, useFormEngine, type FormEngine, type FormSchema } from "./form-engine";

/** What onSubmit may return to report problems the server found. */
export interface SubmitResult {
  /** Errors by field name, shown on those fields. */
  fieldErrors?: Record<string, string>;
  /** A message about the whole form, shown in the ErrorSummary. */
  formError?: string;
}

/** What children and useFormState() receive. */
export interface FormRenderState {
  state: ActionState;
  isPending: boolean;
  /** The message about the whole form after a failed submit. */
  formError?: string;
  /** The error that onSubmit threw, if it did. */
  error?: unknown;
}

export interface FormContextValue {
  engine: FormEngine;
  formRef: RefObject<HTMLFormElement | null>;
  state: FormRenderState;
  /** Counts failed submits (a validator stopped it, or onSubmit failed). The ErrorSummary moves focus on each. */
  focusRequest: number;
  serverErrors: Record<string, string>;
  clearServerError(name: string): void;
  /** Field labels for the ErrorSummary, filled in by each Field. */
  labels: Map<string, string>;
  /** How many ErrorSummary components are mounted. Without one, a failure is announced by the form itself. */
  summaries: RefObject<number>;
  focusField(name: string): boolean;
}

const FormContext = createContext<FormContextValue | null>(null);

export function useFormContext(): FormContextValue {
  const ctx = useContext(FormContext);
  if (!ctx) throw new Error("This component must be used inside a <Form>.");
  return ctx;
}

/** The action state of the nearest Form: idle, pending, success or error. */
export function useFormState(): FormRenderState {
  return useFormContext().state;
}

/**
 * Reads what is typed in the form, for derived display such as a total.
 * Pass a selector and return something cheap to compare, like a number.
 * The calculation is yours; the form only hands over the values.
 */
export function useFormValues<TValues = Record<string, any>, TResult = TValues>(select?: (values: TValues) => TResult): TResult {
  const { engine } = useFormContext();
  return useEngineValues(engine as FormEngine<TValues>, (select ?? ((v: TValues) => v as unknown as TResult)) as (v: TValues) => TResult);
}

export interface FormProps<TValues = Record<string, any>>
  extends Omit<FormSpecProps, "defaultValues" | "onSubmit" | "schema" | "children">,
    Omit<FormHTMLAttributes<HTMLFormElement>, keyof FormSpecProps | "className" | "noValidate" | "onReset"> {
  defaultValues: TValues;
  onSubmit: (values: TValues) => void | SubmitResult | Promise<void | SubmitResult>;
  schema?: FormSchema<TValues>;
  children?: ReactNode | ((form: FormRenderState) => ReactNode);
  className?: string;
}

/**
 * A form with its own checks turned off (noValidate): the checks are the
 * validators and schema you pass, so errors look and read the same everywhere.
 * It owns no data fetching: your onSubmit does the work and may return errors.
 */
export function Form<TValues extends Record<string, any> = Record<string, any>>({
  defaultValues,
  onSubmit,
  schema,
  validateOn = formDefaults.validateOn,
  successMessage,
  errorMessage = formDefaults.errorMessage,
  resetOnSuccess = formDefaults.resetOnSuccess,
  children,
  className,
  ...rest
}: FormProps<TValues>) {
  const formRef = useRef<HTMLFormElement>(null);
  const [state, setState] = useState<ActionState>("idle");
  const [error, setError] = useState<unknown>();
  const [formError, setFormError] = useState<string>();
  const [serverErrors, setServerErrors] = useState<Record<string, string>>({});
  const [focusRequest, setFocusRequest] = useState(0);
  const [announcement, setAnnouncement] = useState("");
  const [announceCount, setAnnounceCount] = useState(0);
  const busy = useRef(false);
  const summaries = useRef(0);
  const labels = useMemo(() => new Map<string, string>(), []);
  const onSubmitRef = useRef(onSubmit);
  onSubmitRef.current = onSubmit;

  const announce = (text: string) => {
    setAnnouncement(text);
    setAnnounceCount((n) => n + 1);
  };

  const engine = useFormEngine<TValues>({
    defaultValues,
    schema,
    validateOn,
    onInvalid: () => {
      setFormError(undefined);
      setFocusRequest((n) => n + 1);
    },
    onSubmit: async (values) => {
      if (busy.current) return;
      busy.current = true;
      setState("pending");
      setError(undefined);
      setFormError(undefined);
      setServerErrors({});
      const fail = (message: string) => {
        setState("error");
        setFormError(message);
        setFocusRequest((n) => n + 1);
        if (summaries.current === 0) announce(message);
      };
      try {
        const result = await onSubmitRef.current(values);
        if (result && (result.formError || (result.fieldErrors && Object.keys(result.fieldErrors).length))) {
          setServerErrors(result.fieldErrors ?? {});
          fail(result.formError ?? errorMessage);
        } else {
          setState("success");
          if (successMessage) announce(successMessage);
          if (resetOnSuccess) engine.reset();
        }
      } catch (e) {
        setError(e);
        fail(errorMessage);
      } finally {
        busy.current = false;
      }
    },
  });

  const focusField = useCallback(
    (name: string) => {
      const target = firstFocusable(findFieldRoot(formRef.current, name));
      target?.focus();
      return Boolean(target);
    },
    [],
  );

  const render = useMemo<FormRenderState>(
    () => ({ state, isPending: state === "pending", formError, error }),
    [state, formError, error],
  );

  const context = useMemo<FormContextValue>(
    () => ({
      engine,
      formRef,
      state: render,
      focusRequest,
      serverErrors,
      clearServerError: (name) =>
        setServerErrors((current) => {
          if (!(name in current)) return current;
          const { [name]: _gone, ...next } = current;
          return next;
        }),
      labels,
      summaries,
      focusField,
    }),
    [engine, render, focusRequest, serverErrors, labels, focusField],
  );

  return (
    <FormContext.Provider value={context}>
      <form
        {...rest}
        ref={formRef}
        noValidate
        aria-busy={state === "pending" || undefined}
        className={cx("flex flex-col gap-4", className)}
        onSubmit={(event) => {
          event.preventDefault();
          event.stopPropagation();
          void engine.submit();
        }}
        onReset={(event) => {
          event.preventDefault();
          engine.reset();
          setState("idle");
          setFormError(undefined);
          setServerErrors({});
        }}
      >
        {typeof children === "function" ? children(render) : children}
        {/* Said in words for screen readers; a changing counter makes a repeated message read again. */}
        <div role="status" aria-live="polite" className="sr-only">
          {announcement}
          {announceCount % 2 === 1 ? "" : " "}
        </div>
      </form>
